1	export type Customer = {
2	  yearsWithMHPCO: number;
3	  previousContracts: number;
4	};
5	
6	export type Item = {
7	  type: string;
8	  material?: string;
9	  enchantment?: number;
10	  cursed?: boolean;
11	};
12	
13	const PROCESSING_FEE = 5;
14	
15	const BASE_PREMIUM_BY_ITEM_TYPE: Record<string, number> = {
16	  sword: 100,
17	  amulet: 60,
18	  staff: 80,
19	};
20	
21	const basePremiumOf = (item: Item): number =>
22	  BASE_PREMIUM_BY_ITEM_TYPE[item.type];
23	
24	export const quote = (customer: Customer, items: Item[]): number => {
25	  const basePremium = items
26	    .map(basePremiumOf)
27	    .reduce((sum, premium) => sum + premium, 0);
28	  return basePremium + PROCESSING_FEE;
29	};
30	
31	export const claim = (): number => {
32	  return undefined as unknown as number;
33	};
